class FfiConverterBoolean: FfiConverter<bool, sbyte> {
    public static FfiConverterBoolean INSTANCE = new FfiConverterBoolean();

    public override bool Lift(sbyte value) {
        return value != 0;
    }

    public override bool Read(BigEndianStream stream) {
        return Lift(stream.ReadSByte());
    }

    public override sbyte Lower(bool value) {
        return value ? (sbyte)1 : (sbyte)0;
    }

    public override int AllocationSize(bool value) {
        return (sbyte)1;
    }

    public override void Write(bool value, BigEndianStream stream) {
        stream.WriteSByte(Lower(value));
    }
}



class FfiConverterString: FfiConverter<string, RustBuffer> {
    public static FfiConverterString INSTANCE = new FfiConverterString();

    // Note: we don't inherit from FfiConverterRustBuffer, because we use a
    // special encoding when lowering/lifting.  We can use `RustBuffer.len` to
    // store our length and avoid writing it out to the buffer.
    public override string Lift(RustBuffer value) {
        try {
            var bytes = value.AsStream().ReadBytes(Convert.ToInt32(value.len));
            return System.Text.Encoding.UTF8.GetString(bytes);
        } finally {
            RustBuffer.Free(value);
        }
    }

    public override string Read(BigEndianStream stream) {
        var length = stream.ReadInt();
        var bytes = stream.ReadBytes(length);
        return System.Text.Encoding.UTF8.GetString(bytes);
    }

    public override RustBuffer Lower(string value) {
        var bytes = System.Text.Encoding.UTF8.GetBytes(value);
        var rbuf = RustBuffer.Alloc(bytes.Length);
        rbuf.AsWriteableStream().WriteBytes(bytes);
        return rbuf;
    }

    // TODO(CS)
    // We aren't sure exactly how many bytes our string will be once it's UTF-8
    // encoded.  Allocate 3 bytes per unicode codepoint which will always be
    // enough.
    public override int AllocationSize(string value) {
        const int sizeForLength = 4;
        var sizeForString = System.Text.Encoding.UTF8.GetByteCount(value);
        return sizeForLength + sizeForString;
    }

    public override void Write(string value, BigEndianStream stream) {
        var bytes = System.Text.Encoding.UTF8.GetBytes(value);
        stream.WriteInt(bytes.Length);
        stream.WriteBytes(bytes);
    }
}



/// <summary>
/// The main Pumas Library API handle.
///
/// Create an instance with `FfiPumasApi::new()` or `FfiPumasApi::with_options()`,
/// then call methods to manage models, search HuggingFace, etc.
///
/// # Example (Python)
///
/// ```python
/// api = await FfiPumasApi.new("/path/to/launcher-root")
/// models = await api.list_models()
/// results = await api.search_hf_models("llama", None, 10)
/// ```
/// </summary>
internal interface IFfiPumasApi {
    /// <summary>
    /// Cancel an active HuggingFace download.
    ///
    /// Returns `true` if a download was found and cancelled.
    /// </summary>
    /// <exception cref="FfiException"></exception>
    Task<bool> CancelHfDownload(String @downloadId);
    /// <summary>
    /// Delete a model and all its links.
    /// </summary>
    /// <exception cref="FfiException"></exception>
    Task<DeleteModelResponse> DeleteModel(String @modelId);
    /// <summary>
    /// Get disk space information for the launcher root.
    /// </summary>
    /// <exception cref="FfiException"></exception>
    Task<DiskSpaceResponse> GetDiskSpace();
    /// <summary>
    /// Get the progress of an active HuggingFace download.
    ///
    /// Returns `None` if the download ID is not found.
    /// </summary>
    Task<ModelDownloadProgress?> GetHfDownloadProgress(String @downloadId);
    /// <summary>
    /// Get a single model by its ID.
    /// </summary>
    /// <exception cref="FfiException"></exception>
    Task<FfiModelRecord?> GetModel(String @modelId);
    /// <summary>
    /// Import a model from a local file path.
    /// </summary>
    /// <exception cref="FfiException"></exception>
    Task<ModelImportResult> ImportModel(ModelImportSpec @spec);
    /// <summary>
    /// Check if the network is currently online.
    /// </summary>
    bool IsOnline();
    /// <summary>
    /// List all models in the library.
    /// </summary>
    /// <exception cref="FfiException"></exception>
    Task<List<FfiModelRecord>> ListModels();
    /// <summary>
    /// Search for models on HuggingFace.
    ///
    /// - `query`: Search query string
    /// - `kind`: Optional model type filter (e.g. "text-generation")
    /// - `limit`: Maximum number of results
    /// </summary>
    /// <exception cref="FfiException"></exception>
    Task<List<FfiHuggingFaceModel>> SearchHfModels(String @query, String? @kind, ulong @limit);
    /// <summary>
    /// Search models using full-text search.
    /// </summary>
    /// <exception cref="FfiException"></exception>
    Task<FfiSearchResult> SearchModels(String @query, ulong @limit, ulong @offset);
    /// <summary>
    /// Start downloading a model from HuggingFace.
    ///
    /// Returns a download ID that can be used to track progress or cancel.
    /// </summary>
    /// <exception cref="FfiException"></exception>
    Task<String> StartHfDownload(DownloadRequest @request);
}
