            + FfiConverterUInt64.INSTANCE.AllocationSize(value.@totalCount)
            + FfiConverterDouble.INSTANCE.AllocationSize(value.@queryTimeMs)
            + FfiConverterString.INSTANCE.AllocationSize(value.@query);
    }

    public override void Write(FfiSearchResult value, BigEndianStream stream) {
            FfiConverterSequenceTypeFfiModelRecord.INSTANCE.Write(value.@models, stream);
            FfiConverterUInt64.INSTANCE.Write(value.@totalCount, stream);
            FfiConverterDouble.INSTANCE.Write(value.@queryTimeMs, stream);
            FfiConverterString.INSTANCE.Write(value.@query, stream);
    }
}





