class FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException>, CallStatusErrorHandler<FfiException> {
    public static FfiConverterTypeFfiError INSTANCE = new FfiConverterTypeFfiError();

    public override FfiException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new FfiException.Network(
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new FfiException.Timeout(
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new FfiException.RateLimited(
                    FfiConverterString.INSTANCE.Read(stream));
            case 4:
                return new FfiException.Database(
                    FfiConverterString.INSTANCE.Read(stream));
            case 5:
                return new FfiException.Io(
                    FfiConverterString.INSTANCE.Read(stream));
            case 6:
                return new FfiException.NotFound(
                    FfiConverterString.INSTANCE.Read(stream));
            case 7:
                return new FfiException.Version(
                    FfiConverterString.INSTANCE.Read(stream));
            case 8:
                return new FfiException.Model(
                    FfiConverterString.INSTANCE.Read(stream));
            case 9:
                return new FfiException.Download(
                    FfiConverterString.INSTANCE.Read(stream));
            case 10:
                return new FfiException.Validation(
                    FfiConverterString.INSTANCE.Read(stream));
            case 11:
                return new FfiException.Config(
                    FfiConverterString.INSTANCE.Read(stream));
            case 12:
                return new FfiException.Cancelled();
            case 13:
                return new FfiException.Other(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeFfiError.Read()", value));
        }
    }

    public override int AllocationSize(FfiException value) {
        switch (value) {

            case FfiException.Network variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case FfiException.Timeout variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case FfiException.RateLimited variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case FfiException.Database variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case FfiException.Io variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case FfiException.NotFound variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@resource);

            case FfiException.Version variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case FfiException.Model variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case FfiException.Download variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case FfiException.Validation variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case FfiException.Config variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case FfiException.Cancelled variant_value:
                return 4;

            case FfiException.Other variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@v1);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeFfiError.AllocationSize()", value));
        }
    }

    public override void Write(FfiException value, BigEndianStream stream) {
        switch (value) {
            case FfiException.Network variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case FfiException.Timeout variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case FfiException.RateLimited variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case FfiException.Database variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case FfiException.Io variant_value:
                stream.WriteInt(5);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case FfiException.NotFound variant_value:
                stream.WriteInt(6);
                FfiConverterString.INSTANCE.Write(variant_value.@resource, stream);
                break;
            case FfiException.Version variant_value:
                stream.WriteInt(7);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case FfiException.Model variant_value:
                stream.WriteInt(8);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case FfiException.Download variant_value:
